#include "Bytecode.h"
#include <sstream>
#include <unordered_set>
namespace jspp { namespace {
struct Loop { std::size_t scope_depth=0;std::vector<std::size_t>breaks,continues; };
struct Compiler {
 Bytecode&b;std::string&error;bool in_function=false;std::size_t scope_depth=0;std::vector<std::unordered_set<std::string>>scopes{{}};std::vector<Loop>loops;
 Compiler(Bytecode&code,std::string&message,bool function=false):b(code),error(message),in_function(function){}
 std::size_t emit(Op op){b.instructions.push_back({op});return b.instructions.size()-1;}
 void patch(std::size_t at,std::size_t target){b.instructions[at].target=target;}
 bool declare(const std::string&name){if(!scopes.back().insert(name).second){error="duplicate binding '"+name+"'";return false;}return true;}
 void unwind(std::size_t target){for(auto n=scope_depth;n>target;--n)emit(Op::LeaveScope);}
 bool function(const Expr&e){
  auto prototype=std::make_shared<FunctionPrototype>();prototype->name=e.text;prototype->parameters=e.parameters;prototype->code=std::make_shared<Bytecode>();
  Compiler child(*prototype->code,error,true);for(const auto&p:e.parameters)if(!child.declare(p))return false;
  const auto&body=e.function_body->body;for(const auto&s:body){if(!child.stmt(s))return false;child.emit(Op::Pop);}child.emit(Op::PushUndefined);child.emit(Op::Return);
  b.functions.push_back(prototype);b.instructions.push_back({Op::MakeFunction,0,false,{},b.functions.size()-1});return true;
 }
 bool expr(const Expr&e){
  switch(e.kind){case ExprKind::Number:b.instructions.push_back({Op::PushNumber,e.number});return true;case ExprKind::String:b.instructions.push_back({Op::PushString,0,false,e.text});return true;case ExprKind::Boolean:b.instructions.push_back({Op::PushBoolean,0,e.text=="true"});return true;case ExprKind::Null:emit(Op::PushNull);return true;case ExprKind::Undefined:emit(Op::PushUndefined);return true;case ExprKind::Identifier:b.instructions.push_back({Op::Load,0,false,e.text});return true;case ExprKind::This:b.instructions.push_back({Op::Load,0,false,"this"});return true;case ExprKind::Object:emit(Op::MakeObject);for(std::size_t i=0;i<e.arguments.size();++i){b.instructions.push_back({Op::PushString,0,false,e.keys[i]});if(!expr(*e.arguments[i]))return false;emit(Op::DefineProperty);}return true;case ExprKind::Array:emit(Op::MakeArray);for(const auto&item:e.arguments){if(!expr(*item))return false;emit(Op::ArrayPush);}return true;case ExprKind::Property:if(!expr(*e.left))return false;if(e.computed){if(!expr(*e.right))return false;}else b.instructions.push_back({Op::PushString,0,false,e.text});emit(Op::GetProperty);return true;case ExprKind::Function:return function(e);case ExprKind::Call:if(e.left->kind==ExprKind::Property){if(!expr(*e.left->left))return false;if(e.left->computed){if(!expr(*e.left->right))return false;}else b.instructions.push_back({Op::PushString,0,false,e.left->text});for(const auto&arg:e.arguments)if(!expr(*arg))return false;b.instructions.push_back({Op::CallMethod,0,false,{},e.arguments.size()});}else{if(!expr(*e.left))return false;for(const auto&arg:e.arguments)if(!expr(*arg))return false;b.instructions.push_back({Op::Call,0,false,{},e.arguments.size()});}return true;case ExprKind::New:if(!expr(*e.left))return false;for(const auto&arg:e.arguments)if(!expr(*arg))return false;b.instructions.push_back({Op::Construct,0,false,{},e.arguments.size()});return true;case ExprKind::Unary:if(!expr(*e.right))return false;if(e.text=="+")emit(Op::UnaryPlus);else if(e.text=="-")emit(Op::Negate);else emit(Op::Not);return true;case ExprKind::Assignment:if(e.left){if(!expr(*e.left->left))return false;if(e.left->computed){if(!expr(*e.left->right))return false;}else b.instructions.push_back({Op::PushString,0,false,e.left->text});if(!expr(*e.right))return false;emit(Op::SetProperty);}else{if(!expr(*e.right))return false;b.instructions.push_back({Op::Store,0,false,e.text});}return true;case ExprKind::Conditional:{if(!expr(*e.left))return false;auto no=emit(Op::JumpIfFalse);if(!expr(*e.right))return false;auto end=emit(Op::Jump);patch(no,b.instructions.size());if(!expr(*e.third))return false;patch(end,b.instructions.size());return true;}case ExprKind::Binary:break;}
  if(e.text=="&&"||e.text=="||"){if(!expr(*e.left))return false;emit(Op::Duplicate);auto done=emit(e.text=="&&"?Op::JumpIfFalse:Op::JumpIfTrue);emit(Op::Pop);if(!expr(*e.right))return false;patch(done,b.instructions.size());return true;}
  if(!expr(*e.left)||!expr(*e.right))return false;
  const auto&o=e.text;if(o=="+")emit(Op::Add);else if(o=="-")emit(Op::Subtract);else if(o=="*")emit(Op::Multiply);else if(o=="/")emit(Op::Divide);else if(o=="%")emit(Op::Remainder);else if(o=="==")emit(Op::Equal);else if(o=="!=")emit(Op::NotEqual);else if(o=="===")emit(Op::StrictEqual);else if(o=="!==")emit(Op::StrictNotEqual);else if(o=="<")emit(Op::Less);else if(o=="<=")emit(Op::LessEqual);else if(o==">")emit(Op::Greater);else if(o==">=")emit(Op::GreaterEqual);else if(o=="instanceof")emit(Op::InstanceOf);else{error="unsupported binary operator";return false;}return true;
 }
 bool stmt(const Statement&s){const auto begin=b.instructions.size();const auto ok=stmt_impl(s);for(auto i=begin;i<b.instructions.size();++i)if(!b.instructions[i].line){b.instructions[i].line=s.line;b.instructions[i].column=s.column;}return ok;}
 bool stmt_impl(const Statement&s){
  switch(s.kind){case StatementKind::Empty:emit(Op::PushUndefined);return true;case StatementKind::Expression:return expr(*s.expression);
   case StatementKind::Declaration:if(!declare(s.name)||!expr(*s.expression))return false;b.instructions.push_back({Op::Declare,0,s.constant,s.name});emit(Op::PushUndefined);return true;
   case StatementKind::FunctionDeclaration:if(!declare(s.name)||!expr(*s.expression))return false;b.instructions.push_back({Op::Declare,0,true,s.name});emit(Op::PushUndefined);return true;
   case StatementKind::Return:if(!in_function){error="return outside function";return false;}if(s.expression){if(!expr(*s.expression))return false;}else emit(Op::PushUndefined);unwind(0);emit(Op::Return);return true;
   case StatementKind::Throw:if(!expr(*s.expression))return false;emit(Op::Throw);return true;
   case StatementKind::Try:{const auto protected_begin=b.instructions.size(),handler_scope=scope_depth;if(!stmt(*s.try_branch))return false;const auto protected_end=b.instructions.size();if(!s.finally_branch){auto done=emit(Op::Jump);const auto handler_target=b.instructions.size();emit(Op::EnterScope);++scope_depth;scopes.push_back({});if(s.catch_name.empty())emit(Op::Pop);else{if(!declare(s.catch_name))return false;b.instructions.push_back({Op::Declare,0,false,s.catch_name});}if(!stmt(*s.catch_branch))return false;emit(Op::LeaveScope);scopes.pop_back();--scope_depth;patch(done,b.instructions.size());b.handlers.push_back({protected_begin,protected_end,handler_target,handler_scope,0});return true;}if(s.catch_branch){auto caught=emit(Op::Jump);const auto handler_target=b.instructions.size();emit(Op::EnterScope);++scope_depth;scopes.push_back({});if(s.catch_name.empty())emit(Op::Pop);else{if(!declare(s.catch_name))return false;b.instructions.push_back({Op::Declare,0,false,s.catch_name});}if(!stmt(*s.catch_branch))return false;emit(Op::LeaveScope);scopes.pop_back();--scope_depth;patch(caught,b.instructions.size());b.handlers.push_back({protected_begin,protected_end,handler_target,handler_scope,0});}auto begin_completion=emit(Op::BeginCompletion);const auto cleanup_end=b.instructions.size(),cleanup_target=b.instructions.size();if(!stmt(*s.finally_branch))return false;emit(Op::Pop);emit(Op::ResumeCompletion);const auto continuation=b.instructions.size();patch(begin_completion,continuation);b.cleanups.push_back({protected_begin,cleanup_end,cleanup_target,handler_scope,0});return true;}
   case StatementKind::Block:{emit(Op::EnterScope);++scope_depth;scopes.push_back({});if(s.body.empty())emit(Op::PushUndefined);for(std::size_t i=0;i<s.body.size();++i){if(!stmt(s.body[i]))return false;if(i+1<s.body.size())emit(Op::Pop);}emit(Op::LeaveScope);scopes.pop_back();--scope_depth;return true;}
   case StatementKind::If:{if(!expr(*s.condition))return false;auto otherwise=emit(Op::JumpIfFalse);if(!stmt(*s.then_branch))return false;auto done=emit(Op::Jump);patch(otherwise,b.instructions.size());if(s.else_branch){if(!stmt(*s.else_branch))return false;}else emit(Op::PushUndefined);patch(done,b.instructions.size());return true;}
   case StatementKind::While:{const auto condition=b.instructions.size();if(!expr(*s.condition))return false;auto done=emit(Op::JumpIfFalse);loops.push_back({scope_depth,{},{}});if(!stmt(*s.then_branch))return false;emit(Op::Pop);for(auto x:loops.back().continues)patch(x,condition);b.instructions.push_back({Op::Jump,0,false,{},condition});const auto end=b.instructions.size();patch(done,end);for(auto x:loops.back().breaks)patch(x,end);loops.pop_back();emit(Op::PushUndefined);return true;}
   case StatementKind::For:{if(s.initializer){if(!stmt(*s.initializer))return false;emit(Op::Pop);}const auto condition=b.instructions.size();if(s.condition){if(!expr(*s.condition))return false;}else b.instructions.push_back({Op::PushBoolean,0,true});auto done=emit(Op::JumpIfFalse);loops.push_back({scope_depth,{},{}});if(!stmt(*s.then_branch))return false;emit(Op::Pop);const auto update=b.instructions.size();for(auto x:loops.back().continues)patch(x,update);if(s.update){if(!expr(*s.update))return false;emit(Op::Pop);}b.instructions.push_back({Op::Jump,0,false,{},condition});const auto end=b.instructions.size();patch(done,end);for(auto x:loops.back().breaks)patch(x,end);loops.pop_back();emit(Op::PushUndefined);return true;}
   case StatementKind::Break:if(loops.empty()){error="break outside loop";return false;}loops.back().breaks.push_back(emit(Op::BreakCompletion));b.instructions.back().number=static_cast<double>(loops.back().scope_depth);return true;
   case StatementKind::Continue:if(loops.empty()){error="continue outside loop";return false;}loops.back().continues.push_back(emit(Op::ContinueCompletion));b.instructions.back().number=static_cast<double>(loops.back().scope_depth);return true;
  }return false;
 }
}; }
bool compile(const Program&p,Bytecode&b,std::string&error){Compiler c(b,error);for(std::size_t i=0;i<p.statements.size();++i){if(!c.stmt(p.statements[i]))return false;if(i+1<p.statements.size())c.emit(Op::Pop);}if(p.statements.empty())c.emit(Op::PushUndefined);return true;}
static const char*name(Op o){static const char*n[]={"push.undefined","push.null","push.boolean","push.number","push.string","load","declare","store","scope.enter","scope.leave","function","call","call.method","construct","return","throw","completion.begin","completion.resume","completion.break","completion.continue","object","array","property.define","array.push","property.get","property.set","unary.plus","negate","not","add","subtract","multiply","divide","remainder","equal","not.equal","strict.equal","strict.not.equal","less","less.equal","greater","greater.equal","instanceof","pop","duplicate","jump","jump.if.false","jump.if.true"};return n[static_cast<int>(o)];}
std::string disassemble(const Bytecode&b){std::ostringstream out;for(std::size_t i=0;i<b.instructions.size();++i){const auto&x=b.instructions[i];out<<i<<" "<<name(x.op);if(x.op==Op::PushNumber)out<<" "<<x.number;else if(x.op==Op::PushBoolean)out<<" "<<(x.boolean?"true":"false");else if(!x.text.empty())out<<" "<<x.text;if(x.op==Op::Jump||x.op==Op::JumpIfFalse||x.op==Op::JumpIfTrue||x.op==Op::BeginCompletion||x.op==Op::BreakCompletion||x.op==Op::ContinueCompletion||x.op==Op::MakeFunction||x.op==Op::Call||x.op==Op::CallMethod||x.op==Op::Construct)out<<" "<<x.target;if(x.line)out<<" @"<<x.line<<":"<<x.column;out<<"\n";}return out.str();}
}
